"""Build a reproducible Russian report from the data generated by the experiment."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
def inp(f):return json.loads((ROOT/f).read_bytes())
def f(x,n=2):return format(x,f'.{n}f').replace('.',',')
def p(x):return f(100*x)
def ci(s):return '['+p(s[0])+'; '+p(s[1])+']'
def report():
    res=inp('results.json');metrics=res['metrics'];pairs=res['paired'];tab=inp('table1.json');ck=inp('trained-checkpoint.json');w=inp('weight-audit.json')
    m=metrics['related'];s=metrics['skip'];px=metrics['prefix'];d=pairs['related-skip'];D=d['differences'];bench=inp('throughput.json');enc=inp('embedding-cost.json')
    txt=['# Упаковка доказательств после дообучения E5 на ISETrace','',
         'Проверяем, сохраняется ли преимущество дополнения пары «аргумент — результат» после обучения модели ранжировать источники для этой задачи. Использована нативная реализация provenance-unit Dense-FT проекта GraphMemory. Полные веса E5 дообучены на всех 3 894 train-запросах. Из 580 доступных dev-запросов публичный профиль использует 500. Фиксированная тестовая выборка включает 2 000 запросов из 1 207 отдельных траекторий. Seed обучения 13. Пользовательские задачи и команды из траекторий служат текстом для извлечения.',
         '',f"**Основной результат.** При 2 048 токенах парное дополнение получает {m['fs_hits']}/2 000 случаев полного покрытия ({p(m['full_support'])}%), обычный добор skip — {s['fs_hits']}/2 000 ({p(s['full_support'])}%). Разница {p(D['full_support']['estimate'])} п.п., 95% кластерный ДИ {ci(D['full_support']['cluster_ci95'])}. Против skip поштучно {d['fs_wins']} выигрышей, {d['fs_losses']} проигрышей и {d['fs_ties']} совпадений, средняя разница фактически прочитанного {f(D['tokens']['estimate'])} токена.",
         '','## Сравнение способов чтения','',
         '| Политика | FS, случаи | FS, % | Coverage, % | Density, % | F1, % | Средний расход токенов | Блоков |','|---|---:|---:|---:|---:|---:|---:|---:|']
    for a in ('prefix','clip','skip','value','related'):
        v=metrics[a];txt.append(f"| {a} | {v['fs_hits']}/2000 | {p(v['full_support'])} | {p(v['coverage'])} | {p(v['density'])} | {p(v['f1'])} | {f(v['tokens'],1)} | {f(v['nodes'],1)} |")
    txt+=['','FS измеряет наличие всех размеченных символов, Coverage — долю покрытых символов, Density — долю эталонных символов среди прочитанного. Все политики получают один и тот же обученный порядок узлов. Prefix останавливается перед первым переполнением, clip добавляет допустимую часть следующего узла, skip добирает последующие помещающиеся узлы. Value переупорядочивает остаток по score/√tokens. Related первым рассматривает блок противоположной стороны уже выбранного вызова, затем сохраняет исходный порядок.','',
          '| Попарный контраст | Δ FS, п.п. | 95% ДИ | Выигрыши / проигрыши | Δ Coverage, п.п. | Δ токенов |','|---|---:|---:|---:|---:|---:|']
    for name,r in pairs.items():
        d=r['differences'];txt.append(f"| {name} | {p(d['full_support']['estimate'])} | {ci(d['full_support']['cluster_ci95'])} | {r['fs_wins']} / {r['fs_losses']} | {p(d['coverage']['estimate'])} | {f(d['tokens']['estimate'])} |")
    txt+=['','Все интервалы — парный бутстреп с 10 000 выборками целых траекторий. Различия ранжировщиков с меткой frozen получены на тех же ID из R18. Выборка общая для предыдущих исследований, этот повтор проверяет перенос политики на новые оценки узлов.','',
          '## Калибровка обученного ранжировщика','',
          '| Нативный prefix | Наше значение, % | Статья, среднее ± SD по 5 seed, % | Наше − опубликованное среднее, п.п. |','|---|---:|---:|---:|']
    for name in ('coverage_512','coverage_1024','coverage_2048','full_support_2048','recall_5','mrr'):
        r=tab[name];txt.append(f"| {name} | {p(r['single_seed'])} | {p(r['published_five_seed_mean'])} ± {p(r['published_five_seed_sd'])} | {f(r['delta_points'])} |")
    rgcn=100*m['full_support']-77.33
    txt+=['',f"Опубликованный residual R-GCN c нативным prefix имеет 77,33 ± 0,53% Full Support. Наша строка related численно отличается от этого среднего на {f(rgcn)} п.п. Для честного сравнения добавочного вклада порядка чтения на разных архитектурах требуется применение той же упаковки к индивидуальным рангам R-GCN и несколько одинаковых seeds. В статье разность ранжировщиков парно оценивается после усреднения соответствующих 5 seeds. [Таблица 1 авторов](https://arxiv.org/html/2609.25913v3#S6.T1)",'',
          '## Контроль обучения и вычислительные расходы','',
          f"Все 26 650 авторских обучающих пар дали 5 330 троек и 337 шагов. При выборе лучшей из epoch 0 и 1 по метрике dev_recall_at_5 получено {f(float(ck['value']),5)}. Сверка исходного и выбранного encoder обнаружила изменения в {w['changed_tensors']} из {w['total_tensors']} тензоров, относительная L2-разность весов {f(w['relative_l2'],5)}. Закреплены SHA каждой части чекпойнта; сами веса хранятся на D. Исходный run со всеми проверками dev занял {f(ck['seconds']/60,1)} мин. Отдельно переиндексация всех {enc['complete']} уникальных тестовых строк — {f(enc['seconds']/60,1)} мин, FP32, TF32 выключен, RTX 3090. Хеш планов и чекпойнта зафиксирован раньше тестовых прогнозов, поштучные прогнозы — раньше тестовой оценки.",
          '',"Оригинальный архив TeX v3 содержит девять файлов — текст, библиографию, служебные файлы и четыре PDF-фигуры. В проверенном дереве GitHub (329 записей), официальных releases/tags и обнаруженных HF-репозиториях не обнаружены отдельные ранги или чекпойнты residual R-GCN. В public-artifact-audit.json перечислены проверенные URLs, содержимое и SHA. Для следующего прямого сравнения R-GCN нужны его индивидуальные прогнозы либо воспроизведение графового обучения. В train/dev-проекции 300 931 дополнительная уникальная PU/query строка относительно test. При наблюдаемом ранее темпе E5 FP32 только эта часть соответствует примерно 27 минутам; цена непроекционных узлов и 15 эпох графа требует отдельного замера. [Код и конфигурации](https://github.com/xiaoqi-7/GraphMemory/tree/df29287116fa1565b3fd6b485022cd6090dc0b27)"]
    direct=inp('direct-agreement.json');bounds=inp('published-seed-bounds.json');timing=inp('rank-only-cost.json')
    txt+=['','## Дополнительная верификация','',
          f"Независимый прямой CPU-вызов авторского DenseTaskRetriever на восьми заранее хеш-отобранных запросах использовал сохранённый обученный checkpoint. Совпало top-1 на {direct['totals']['top1']}/8, top-5 в точном порядке на {direct['totals']['top5_order']}/8 и полная перестановка на {direct['totals']['all_order']}/8. Максимальная абсолютная разность оценок {direct['max_abs']:.3g}.",
          '',f"Одна тестовая задача изменяет FS отдельного seed на 0,05 п.п. При среднем по пяти seed и округлённом выборочном SD можно ограничить отдельные значения. Для R-GCN таблица допускает {bounds['residual_rgcn']['unordered_feasible_count']} неупорядоченных пятёрок целых чисел попаданий и значения отдельного seed от {f(bounds['residual_rgcn']['min_possible_percent'])} до {f(bounds['residual_rgcn']['max_possible_percent'])}%. Для PU Dense-FT диапазон {f(bounds['pu_dense_ft']['min_possible_percent'])}–{f(bounds['pu_dense_ft']['max_possible_percent'])}%. Эти интервалы — арифметически возможные значения отчётных результатов, не доверительные интервалы и не восстановленные результаты конкретного seed.",
          '',f"При наличии исходных рангов R-GCN сам постпроцессинг недорог. Для {timing['scored_candidates']} элементов уже имеющихся рангов R18 E5 при той же форме входа декодирование и подготовка метаданных всех 2 000 задач заняли {f(timing['decode_validate_prepare_source_metadata_seconds'])} с CPU, применение paired имело медиану {f(timing['median_pack_seconds'],3)} с за пять повторов. Для R-GCN это ориентир по данным той же размерности.",
          '',"Во время запуска первая попытка read-only подключения к SQLite остановилась до первого test-вектора. Исправлен параметр URI для Windows, зафиксировано нулевое число строк, сохранены исходный SHA, код и stderr. Повтор использовал те же данные, обученные веса и параметры."]
    txt+=['','**Доступ к разметке.** Preprocessor prepare.py вызывает авторский _read_queries для всего смешанного raw JSONL. Он десериализует и записи test, включая вложенные поля gold, прежде чем отфильтровать 3 894 train и 500 dev ID. Эти test-метки не использовались при создании положительных/отрицательных примеров, вычислении loss или выборе checkpoint. Это программная изоляция по разделам внутри процесса с физическим доступом к общей разметке. Поисковые ранги были запечатаны до оценивания. Класс исследователя также имел доступ к прежним агрегатам R18 на том же test. Подтверждающие проверки собраны в leakage-audit.json.']
    feasibility=inp('rgcn-feasibility.json');hw=inp('rgcn-capacity.json')
    txt+=['','**Осуществимость нативного R-GCN.** Повторное построение графов для всех 3 948 используемых траекторий дало '+str(feasibility['all_splits_unique'])+' уникальных текстов узлов и запросов. Требуется '+str(feasibility['all_missing_independent_of_test'])+' новых строк относительно текущего кэша. Развёрнутый авторский train/dev mmap имеет объём '+f(feasibility['train_dev_mmap_gib'])+' GiB. Пакет из 128 реальных train-запросов дал '+str(hw['nodes'])+' узлов и '+str(hw['message_edges'])+' двунаправленных рёбер после нативной фильтрации. На RTX 3090 три нативных слоя 256/14 на этой топологии прошли forward/backward AdamW с пиком '+f(hw['peak_allocated_gib'])+' GiB. Тест использует синтетические замороженные признаки и скалярную диагностическую loss. Он проверяет вместимость рабочего графового ядра, но не качество R-GCN, пиковую RAM полного процесса или все batch. Отдельные метки рёбер не требуются: связи строит исходный код, supervision берётся из выпущенных символьных spans.']
    (ROOT/'REPORT_RU.md').write_bytes(('\n'.join(txt)+'\n').encode())
if __name__=='__main__':report()
